49	        public J.MethodInvocation visitMethodInvocation(J.MethodInvocation method, ExecutionContext executionContext) {
50	            method = super.visitMethodInvocation(method, executionContext);
51	
52	            JavaType.Method methodType = method.getMethodType();
53	
54	            if (methodType == null) {
55	                return method;
56	            }
57	
58	            String methodName = method.getSimpleName();
59	            JavaType.FullyQualified fullyQualified = methodType.getDeclaringType();
60	
61	            if (!shouldChangeGetter(fullyQualified)) {
62	                return method;
63	            }
64	
65	            if (NamingUtils.isGetter(methodName)) {
